VX=[['拉丁 vox，词干 voc-，宾格 vocem','声音、话语；与 vocare“呼唤”同族']]
VC=[['拉丁 vocare','呼唤、叫来、称呼；与 vox“声音”同族']]
VOICE=VX+[['古法语／盎格鲁法语 voiz、vois → 中古英语 voice、voys','声音、话语'],['英语 voice，另由名词形成动词','嗓音；表达意见的渠道；说出、表达']]
VOCAL=VX+[['拉丁 vocalis → 古法语 vocal／直接借入 → 英语 vocal','出声的、与嗓音有关的；后来也形容公开表达意见']]
VOCAB=VC+[['拉丁 vocabulum','称呼、名字、词'],['中世纪拉丁 vocabularium → 英语 vocabulary','词汇表 → 一个人、语言或领域的词汇总量']]
VOCATION=VC+[['拉丁 vocatio → 法语 vocacion／直接借入 → 英语 vocation','召唤，尤其宗教召唤 → 志业、职业']]
AD=VC+[['拉丁 ad- 向、到 + vocare → advocare','叫到身边来，召来帮助']]
AV=AD+[['古法语 avoer／盎格鲁法语 avouer → 中古英语 avowen → avow','承认、公开站到一边支持 → 坦率声明、承认']]
DIS=AD+[['古法语 avoer／avouer → desavouer','承认、支持 → 否认联系、拒绝承认'],['中古英语 disavowen → 英语 disavow','否认、撇清关系、不承认']]
IN=VC+[['拉丁 in- 向、在上 + vocare → invocare','呼求、请求援助'],['古法语 envoquer → 中古英语 envoken → invoke','祈求；援引权威、规则；调用程序']]
EVLAT=VC+[['拉丁 ex- 向外 + vocare → evocare','叫出来、召出、唤起']]
EV=EVLAT+[['法语 évoquer／直接拉丁借入 → 英语 evoke','唤起记忆、感觉；召出']]
EVN=EVLAT+[['拉丁 evocatio → 法语 évocation／直接借入 → 英语 evocation','召出、唤起；使某种场景在心中出现的表达']]
PROLAT=VC+[['拉丁 pro- 向前、向外 + vocare → provocare','叫出来挑战；激起反应']]
PRO=PROLAT+[['古法语 provoker、provochier／直接借入 → 中古英语 provoken → provoke','激起、刺激；惹怒、挑衅']]
PROADJ=PROLAT+[['拉丁 provocatus → 晚期拉丁 provocativus → 法语 provocatif','激起的 → 能激起反应的'],['英语 provocative','挑衅的；引起思考的；挑逗的']]
REV=VC+[['拉丁 re- 回 + vocare → revocare','叫回来、收回'],['古法语 revoquer → 中古英语 revoken → revoke','撤回、取消原有许可或决定']]
REVABLE=VC+[['拉丁 revocare → revocabilis','收回 → 可以收回的'],['古法语 revocable／直接借入 → 英语 revocable','可撤销的']]
IRREV=VC+[['拉丁 revocare → revocabilis → 否定 in- + revocabilis → irrevocabilis','收回 → 可以收回 → 不可收回；n 在 r 前同化'],['法语 irrévocable／直接借入 → 英语 irrevocable','不可撤销的；不能改变的']]
CONLAT=VC+[['拉丁 com- 一起 + vocare → convocare','把人叫到一起']]
CON=CONLAT+[['法语 convoquer → 英语 convoke','正式召集会议、集会']]
EQUI=VX+[['晚期拉丁 aequi- 相同 + voc- 声音 → aequivocus','声音相同而意义可能不同；含混'],['英语 equivocal，采用 -al 形容词形式','有多种解释的；态度或证据不明确的']]
VOUCH=VC+[['法语之前的罗曼语音形变化有不同重构','通常联系 vocare 的派生形式；中间形式不作定论'],['古法语 vocher／盎格鲁法语 voucher → 中古英语 vouchen → vouch','叫人来作证、担保 → 为真实性或可靠性作保证']]
